/**
 * Workbench shell components (Phase 1): activity bar / side bar / editor
 * area (tab strip) / bottom panel / status bar, rendered into a fixed
 * right-docked root. Written with React.createElement (no JSX) so the
 * client bundle needs no jsx-runtime handling.
 *
 * Rendering model: the shell reads registries and layout through
 * useSyncExternalStore (both are synchronous snapshots), so any
 * register/unregister or layout patch re-renders the affected parts.
 */
import { createElement, Fragment, lazy, Suspense, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import type { ComponentType, ReactNode } from 'react'
import type {
  ActivityBarItemDefinition,
  DockPosition,
  EditorOpenSeed,
  EditorTab,
  FloatingWindow,
  IconRef,
  IconSpec,
  ViewDefinition,
  ViewProps,
  WorkbenchContext,
  WorkbenchLayout,
  WorkbenchService,
} from './contract.ts'
import { FLOATING_MIN_HEIGHT, FLOATING_MIN_WIDTH } from './ui-constants.ts'
import { DOCK_HOVER_SCALE_DEFAULT, DOCK_HOVER_SCALE_SETTING_ID, DOCK_NEAR_SCALE_DEFAULT, DOCK_NEAR_SCALE_SETTING_ID, DOCK_RESERVE_SETTING_ID, DOCK_SETTINGS_ACTIVITY_ID } from './settings.ts'
import { dockReservePx } from './internal/dock-space.ts'
import type { LayoutStore } from './layout.ts'
import { reorderActivity } from './layout.ts'
import { ContextMenu, type ContextMenuItem, type ContextMenuState } from './context-menu'
import { SettingsWindow } from './SettingsWindow.tsx'
import { isDockEnglish, settingsLabels } from './internal/localization.ts'

/** Sort helper shared by item lists. */
function byOrder<T extends { order?: number }>(a: T, b: T): number {
  return (a.order ?? 100) - (b.order ?? 100)
}

/** The dock bar element whose measured size the page reserve is derived from. */
const DOCK_BAR_SELECTOR = '.dsh-wb-activity'

/**
 * Publish the docked edge and the measured offset consumed only by the
 * conversation turn rail. The page shell itself remains full width, so its
 * scrollbar stays at the viewport edge.
 */
function useDockRailOffset(
  rootRef: { current: HTMLDivElement | null },
  dock: DockPosition,
  enabled: boolean,
): void {
  useEffect(() => {
    const body = document.body
    const publish = (): void => {
      const bar = rootRef.current?.querySelector<HTMLElement>(DOCK_BAR_SELECTOR) ?? null
      const offset = enabled && dock === 'right' && bar !== null
        ? dockReservePx('right', bar.getBoundingClientRect(), { width: window.innerWidth, height: window.innerHeight })
        : 0
      if (offset > 0) body.style.setProperty('--dock-turn-rail-offset', `${offset}px`)
      else body.style.removeProperty('--dock-turn-rail-offset')
    }
    body.setAttribute('data-dock', dock)
    publish()
    const bar = rootRef.current?.querySelector<HTMLElement>(DOCK_BAR_SELECTOR) ?? null
    const observer = bar !== null && typeof ResizeObserver !== 'undefined' ? new ResizeObserver(publish) : null
    if (bar !== null) observer?.observe(bar)
    window.addEventListener('resize', publish)
    return () => {
      observer?.disconnect()
      window.removeEventListener('resize', publish)
      body.removeAttribute('data-dock')
      body.style.removeProperty('--dock-turn-rail-offset')
    }
  }, [rootRef, dock, enabled])
}

/**
 * Publish the two magnification factors as custom properties on the shell
 * root. The stylesheet stays static — only the values move — so tuning the
 * sliders in settings never re-injects CSS.
 */
function useDockMagnification(
  rootRef: { current: HTMLDivElement | null },
  hoverScale: number,
  nearScale: number,
): void {
  useEffect(() => {
    const root = rootRef.current
    if (root === null) return
    root.style.setProperty('--dock-icon-hover-scale', String(hoverScale))
    root.style.setProperty('--dock-icon-near-scale', String(nearScale))
    return () => {
      root.style.removeProperty('--dock-icon-hover-scale')
      root.style.removeProperty('--dock-icon-near-scale')
    }
  }, [rootRef, hoverScale, nearScale])
}

/**
 * Render an IconRef: React nodes (emoji, custom components) render as-is;
 * IconSpec values render as an inline SVG `<path>` tinted with currentColor
 * so icons follow the active theme.
 */
function renderIcon(icon: IconRef, size = 16): ReactNode {
  if (icon === null || icon === undefined) return null
  if (typeof icon === 'object' && 'path' in icon) {
    const spec = icon as IconSpec
    return createElement(
      'svg',
      {
        width: spec.size ?? size,
        height: spec.size ?? size,
        viewBox: spec.viewBox ?? '0 0 24 24',
        fill: spec.stroke ? 'none' : 'currentColor',
        stroke: spec.stroke ? 'currentColor' : undefined,
        strokeWidth: spec.stroke ? 2 : undefined,
        strokeLinecap: spec.stroke ? 'round' : undefined,
        strokeLinejoin: spec.stroke ? 'round' : undefined,
        'aria-hidden': true,
      },
      createElement('path', { d: spec.path }),
    )
  }
  return icon as ReactNode
}

/**
 * Resolve a view component: a plain function component renders directly; a
 * zero-arg factory returning a Promise is wrapped in React.lazy (the
 * factory contract — components receive props, factories take none).
 */
function resolveViewComponent(def: ViewDefinition): ComponentType<ViewProps> {
  const component = def.component
  if (component.length === 0) {
    // Zero-arg → lazy factory returning a Promise of the component.
    const factory = component as unknown as () => Promise<ComponentType<ViewProps>>
    return lazy(() => factory().then((resolved) => ({ default: resolved })))
  }
  return component as ComponentType<ViewProps>
}

function titleOf(def: ViewDefinition): string {
  return typeof def.title === 'function' ? def.title() : def.title
}

function renderView(
  ctx: WorkbenchContext,
  def: ViewDefinition,
  viewId: string,
  sessionId: string | undefined,
  active: boolean,
  seed?: unknown,
): ReactNode {
  const Component = resolveViewComponent(def)
  const props: ViewProps = { ctx, viewId, sessionId, active, seed }
  return createElement(
    Suspense,
    { fallback: createElement('div', { className: 'dsh-wb-editor-empty' }, 'Loading…') },
    createElement(Component, props),
  )
}

interface RootProps {
  ctx: WorkbenchContext
  service: WorkbenchService
  store: LayoutStore
}

/** Module-level registry version: bumped on every registry change. */
let registryVersion = 0

/** Docked edge labels for the position menu (zh/en pairs). */
const DOCK_LABEL: Record<DockPosition, { zh: string; en: string }> = {
  left: { zh: '左侧', en: 'Left' },
  right: { zh: '右侧', en: 'Right' },
  top: { zh: '顶部', en: 'Top' },
  bottom: { zh: '底部', en: 'Bottom' },
}

/** True when the DSH UI language is English. The locale plugin keeps
 *  `document.documentElement.lang` in sync with the active locale ('en' for
 *  English, 'zh-CN' for Chinese), so the menu follows the UI language
 *  without importing the locale service. */
function isEnglish(): boolean {
  return isDockEnglish()
}

/** The whole workbench shell. */
export function WorkbenchRoot(props: RootProps): ReactNode {
  const { ctx, service, store } = props
  const layout = useSyncExternalStore(store.subscribe, store.getLayout)
  const registry = useSyncExternalStore(
    (onChange) => service.subscribe(() => { registryVersion += 1; onChange() }),
    () => registryVersion,
  )
  const autoHide = layout.autoHide === 'edge'
  const settingsVersion = useSyncExternalStore(service.onDidChangeSetting, () => service.getHiddenPluginIds().join('\u0000'))
  const hiddenPlugins = useMemo(() => new Set(service.getHiddenPluginIds()), [settingsVersion, service])
  const reserveSpace = useSyncExternalStore(
    service.onDidChangeSetting,
    () => service.getSetting<boolean>(DOCK_RESERVE_SETTING_ID) !== false,
  )
  // Slider-tunable magnification; the defaults back the stylesheet fallbacks.
  const hoverScale = useSyncExternalStore(
    service.onDidChangeSetting,
    () => service.getSetting<number>(DOCK_HOVER_SCALE_SETTING_ID) ?? DOCK_HOVER_SCALE_DEFAULT,
  )
  const nearScale = useSyncExternalStore(
    service.onDidChangeSetting,
    () => service.getSetting<number>(DOCK_NEAR_SCALE_SETTING_ID) ?? DOCK_NEAR_SCALE_DEFAULT,
  )
  const rootRef = useRef<HTMLDivElement>(null)
  const [menu, setMenu] = useState<ContextMenuState | null>(null)
  const [settingsOpen, setSettingsOpen] = useState(false)
  const settingsRestoreRef = useRef<HTMLElement | null>(null)
  const [autoHidden, setAutoHidden] = useState(false)
  const hideTimer = useRef<number | null>(null)
  useEffect(() => () => { if (hideTimer.current !== null) window.clearTimeout(hideTimer.current) }, [])
  useEffect(() => {
    if (autoHide) return
    if (hideTimer.current !== null) {
      window.clearTimeout(hideTimer.current)
      hideTimer.current = null
    }
    setAutoHidden(false)
  }, [autoHide])

  const activityItems = useMemo(() => {
    // User drag order (activityOrder) wins; items not listed keep their
    // registered `order` and are appended in declaration order.
    const all = [...service.getActivityItems()].filter((item) => !hiddenPlugins.has(item.pluginId ?? item.id)).sort(byOrder)
    const byId = new Map(all.map((item) => [item.id, item]))
    const userOrdered = layout.activityOrder.map((id) => byId.get(id)).filter((item): item is ActivityBarItemDefinition => item !== undefined)
    const rest = all.filter((item) => !layout.activityOrder.includes(item.id))
    return [...userOrdered, ...rest]
  }, [registry, service, layout.activityOrder, hiddenPlugins])
  const panels = useMemo(() => [...service.getPanels()].sort(byOrder), [registry, service])
  const editorViews = useMemo(() => [...service.getEditorViews()].sort(byOrder), [registry, service])
  const statusItems = useMemo(() => [...service.getStatusItems()].sort(byOrder), [registry, service])

  const sessionId = useSessionId(ctx)
  const collapsed = layout.activity === null

  // If an active entry is hidden (including when settings are restored), clear
  // activity so the shell cannot point at an unavailable pane.
  useEffect(() => {
    if (layout.activity !== null) {
      const active = service.getActivityItem(layout.activity)
      if (active !== undefined && hiddenPlugins.has(active.pluginId ?? active.id)) store.update({ activity: null })
    }
  }, [layout.activity, hiddenPlugins, service, store])

  // Derive visibility synchronously so a restored/updated hidden activity is
  // never rendered for one frame while the persistence effect clears it.
  const activeActivity = layout.activity === null
    ? undefined
    : (() => {
      const activity = service.getActivityItem(layout.activity)
      return activity !== undefined && !hiddenPlugins.has(activity.pluginId ?? activity.id) ? activity : undefined
    })()
  const activePane = activeActivity === undefined || !layout.sideBarOpen
    ? undefined
    : panels.find((panel) => panel.id === activeActivity.paneId && panel.region === 'sideBar')

  // Dock mode keeps the page shell native; only the conversation turn rail
  // receives an optional right-side offset from useDockRailOffset.

  // Right-click menu: dock position + auto-hide toggle. Labels follow the
  // DSH UI language (see isEnglish). The absorb-native item was removed.
  const openDockMenu = (x: number, y: number, target?: EventTarget | null): void => {
    settingsRestoreRef.current = target instanceof HTMLElement
      ? target.closest('button') ?? target
      : null
    const en = isEnglish()
    const items: ContextMenuItem[] = [
      ...(['left', 'right', 'top', 'bottom'] as DockPosition[]).map((dock) => ({
        label: en ? `Dock to ${DOCK_LABEL[dock].en}` : `停靠到${DOCK_LABEL[dock].zh}`,
        checked: layout.dock === dock,
        onClick: () => store.update({ dock }),
      })),
      {
        label: en ? 'Auto-hide (hide when mouse leaves)' : '自动隐藏（鼠标远离收起）',
        kind: 'checkbox' as const,
        checked: autoHide,
        onClick: () => store.update({ autoHide: autoHide ? 'off' : 'edge' }),
      },
    ]
    items.push({
      label: isEnglish() ? 'Settings' : '设置',
      onClick: () => setSettingsOpen(true),
    })
    setMenu({ x, y, items })
  }

  // Auto-hide state machine: hovering the workbench keeps it visible; after
  // the mouse leaves for ~1s it fades/slides away; the edge hotspot revives.
  const reveal = (): void => {
    if (hideTimer.current !== null) { window.clearTimeout(hideTimer.current); hideTimer.current = null }
    setAutoHidden(false)
  }
  const scheduleHide = (): void => {
    if (!autoHide) return
    if (hideTimer.current !== null) window.clearTimeout(hideTimer.current)
    // A relaxed delay (macOS-like): the shell only slides away after the
    // mouse has stayed outside for a moment, so brushing past never hides it.
    hideTimer.current = window.setTimeout(() => setAutoHidden(true), 900)
  }

  const effectiveAutoHidden = autoHide && autoHidden
  const rootClass = [
    'dsh-wb-root',
    collapsed ? 'wb-collapsed' : undefined,
    effectiveAutoHidden ? 'wb-autohidden' : undefined,
  ].filter(Boolean).join(' ')

  // Publish only the turn-rail offset; the page shell stays full width.
  useDockRailOffset(rootRef, layout.dock, reserveSpace)
  useDockMagnification(rootRef, hoverScale, nearScale)

  return createElement(
    Fragment,
    null,
    createElement(
      'div',
      {
        ref: rootRef,
        className: rootClass,
        'data-dock-shell': '',
        'data-dock': layout.dock,
        'data-mode': 'dock',
        onMouseEnter: reveal,
        onMouseLeave: scheduleHide,
      },
    createElement(ActivityBar, {
      items: activityItems,
      activeId: layout.activity,
      dockMode: true,
      onActivate: (id, trigger) => {
        // The dock's own entry is the settings window, not a side-bar pane:
        // it must never become `layout.activity` (no panel backs it).
        if (id === DOCK_SETTINGS_ACTIVITY_ID) {
          settingsRestoreRef.current = trigger
          setSettingsOpen(true)
          return
        }
        // Clicking the active item again collapses the side bar (VSCode toggle).
        store.update(layout.activity === id ? { activity: null } : { activity: id, sideBarOpen: true })
      },
      onContextMenu: (x, y, target) => openDockMenu(x, y, target),
      onReorder: (draggedId, targetId) => {
        // Reorder by the current visible order and persist the full user
        // order into activityOrder (newly registered items append later).
        const next = reorderActivity(activityItems.map((item) => item.id), draggedId, targetId)
        store.update({ activityOrder: next })
      },
    }),
    createElement('div', { className: 'dsh-wb-body' },
      activePane !== undefined && !collapsed
        ? createElement('div', { className: 'dsh-wb-sidebar' },
          createElement('div', { className: 'dsh-wb-sidebar-header' },
            createElement('span', { className: 'dsh-wb-sidebar-title' }, titleOf(activePane)),
            activePane.headerComponent !== undefined
              ? renderView(ctx, { ...activePane, component: activePane.headerComponent }, activePane.id, sessionId, layout.activity === activeActivity?.id)
              : null,
          ),
          renderView(ctx, activePane, activePane.id, sessionId, layout.activity === activeActivity?.id),
        )
        : null,
      // No editor tabs: the whole editor area is hidden so the shell is
      // just the activity bar + sidebar (no redundant empty column).
      layout.editorTabs.length > 0
        ? createElement('div', { className: 'dsh-wb-main' },
          createElement(EditorArea, {
            ctx,
            service,
            store,
            tabs: layout.editorTabs,
            activeTab: layout.activeEditorTab,
            views: editorViews,
            sessionId,
          }),
          createElement(StatusBar, { items: statusItems, ctx }),
        )
        : null,
    ),
    ),
    // Floating windows and the context menu live OUTSIDE the dock root: they
    // are independent of the auto-hide interaction (hovering them neither
    // reveals nor keeps the dock visible) and are never faded with it.
    createElement(ContextMenu, { menu, onClose: () => setMenu(null) }),
    createElement(SettingsWindow, {
      service,
      open: settingsOpen,
      onClose: () => setSettingsOpen(false),
      restoreFocusRef: settingsRestoreRef,
    }),
    createElement(FloatingWindows, {
      ctx,
      service,
      layout,
      sessionId,
      views: editorViews,
    }),
    // Edge hotspot: a 4px strip on the docked edge (outside the shell, which
    // may be slid off-screen) that revives the workbench on hover. Leaving
    // it re-arms the hide timer so a revived workbench auto-hides again.
    autoHide
      ? createElement('div', {
        className: 'dsh-wb-autohide-hotspot',
         'aria-label': settingsLabels(isEnglish() ? 'en' : 'zh').autoHideHint,
         title: settingsLabels(isEnglish() ? 'en' : 'zh').autoHideHint,
        'data-dock': layout.dock,
        onMouseEnter: reveal,
        onMouseLeave: scheduleHide,
      })
      : null,
  )
}

/** A floating-window resize edge/corner (n/s/e/w + 4 corners). */
type ResizeEdge = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw'

/**
 * The eight resize grips: the shared base class
 * (`dsh-wb-floating-resize`) plus an edge modifier class that positions the
 * grip and sets the resize cursor. 'w'/'n' drags also move the window so
 * the opposite edge stays anchored (handled in the drag math).
 */
const RESIZE_HANDLES: { edge: ResizeEdge; className: string }[] = [
  { edge: 'n', className: 'dsh-wb-resize-n' },
  { edge: 's', className: 'dsh-wb-resize-s' },
  { edge: 'e', className: 'dsh-wb-resize-e' },
  { edge: 'w', className: 'dsh-wb-resize-w' },
  { edge: 'ne', className: 'dsh-wb-resize-ne' },
  { edge: 'nw', className: 'dsh-wb-resize-nw' },
  { edge: 'se', className: 'dsh-wb-resize-se' },
  { edge: 'sw', className: 'dsh-wb-resize-sw' },
]

/** Drag state of a floating window (move or resize, origin snapshot). */
interface FloatingDrag {
  id: string
  mode: 'move' | ResizeEdge
  startX: number
  startY: number
  x: number
  y: number
  width: number
  height: number
}

/** Independent floating windows (view + geometry), draggable/resizable. */
function FloatingWindows(props: {
  ctx: WorkbenchContext
  service: WorkbenchService
  layout: WorkbenchLayout
  sessionId: string | undefined
  views: ViewDefinition[]
}): ReactNode {
  const { ctx, service, layout, sessionId, views } = props
  const viewById = useMemo(() => new Map(views.map((view) => [view.id, view])), [views])
  const dragRef = useRef<FloatingDrag | null>(null)
  const [dragging, setDragging] = useState(false)

  useEffect(() => {
    if (!dragging) return
    const onMove = (event: MouseEvent): void => {
      const drag = dragRef.current
      if (drag === null) return
      const dx = event.clientX - drag.startX
      const dy = event.clientY - drag.startY
      if (drag.mode === 'move') {
        // The service clamps the result, so the title bar can never be
        // dragged out of reach.
        service.moveFloatingWindow(drag.id, drag.x + dx, drag.y + dy)
        return
      }
      // Edge/corner resize. 'e'/'s' grow from the top-left anchor;
      // 'w'/'n' shrink from the opposite edge and shift the window so the
      // far edge stays in place. Min sizes mirror the CSS min-width/height.
      let x = drag.x
      let y = drag.y
      let width = drag.width
      let height = drag.height
      if (drag.mode.includes('e')) width = Math.max(FLOATING_MIN_WIDTH, drag.width + dx)
      if (drag.mode.includes('s')) height = Math.max(FLOATING_MIN_HEIGHT, drag.height + dy)
      if (drag.mode.includes('w')) {
        width = Math.max(FLOATING_MIN_WIDTH, drag.width - dx)
        x = drag.x + drag.width - width
      }
      if (drag.mode.includes('n')) {
        height = Math.max(FLOATING_MIN_HEIGHT, drag.height - dy)
        y = drag.y + drag.height - height
      }
      service.resizeFloatingWindow(drag.id, x, y, width, height)
    }
    const onUp = (): void => { dragRef.current = null; setDragging(false) }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
    return () => {
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
  }, [dragging, service])

  // Keep every floating window's title bar on-screen: a viewport shrink (or
  // geometry restored from a larger screen) is clamped back automatically so
  // no window can be stranded out of reach. Drags clamp live in the service.
  useEffect(() => {
    const onViewportResize = (): void => service.clampFloatingWindowsIntoView()
    window.addEventListener('resize', onViewportResize)
    onViewportResize()
    return () => window.removeEventListener('resize', onViewportResize)
  }, [service])

  const startDrag = (win: FloatingWindow, mode: 'move' | ResizeEdge, event: MouseEvent): void => {
    event.preventDefault()
    dragRef.current = { id: windowKey(win), mode, startX: event.clientX, startY: event.clientY, ...win }
    setDragging(true)
  }

  return createElement(Fragment, null,
    Object.values(layout.floatingWindows).map((win) => {
      const view = viewById.get(win.viewId)
      if (view === undefined) return null
      const id = windowKey(win)
      const seedTitle = (win.seed as { title?: string } | undefined)?.title
      return createElement('div', {
        key: id,
        className: 'dsh-wb-floating',
        style: { left: win.x, top: win.y, width: win.width, height: win.height },
      },
      createElement('div', {
        className: 'dsh-wb-floating-head',
        onMouseDown: (event: MouseEvent) => startDrag(win, 'move', event),
      },
      view.icon !== undefined ? renderIcon(view.icon, 13) : null,
      createElement('span', { className: 'dsh-wb-floating-title' }, seedTitle ?? titleOf(view)),
      createElement('button', {
        className: 'dsh-wb-floating-close',
        title: 'Close',
        onClick: () => service.closeViewInstance(id),
      }, '×'),
      ),
      createElement('div', { className: 'dsh-wb-floating-body' },
        renderView(ctx, view, view.id, sessionId, true, win.seed),
      ),
      // Eight resize grips: each edge and corner. 'w'/'n' drags move the
      // window too (the far edge stays anchored), handled in the drag math.
      RESIZE_HANDLES.map((handle) => createElement('div', {
        key: handle.edge,
        className: `dsh-wb-floating-resize ${handle.className}`,
        onMouseDown: (event: MouseEvent) => startDrag(win, handle.edge, event),
      })),
      )
    }),
  )
}

/** Stable key of a floating window: the instance id. */
function windowKey(win: FloatingWindow): string {
  return win.instanceId
}

function ActivityBar(props: {
  items: ActivityBarItemDefinition[]
  activeId: string | null
  dockMode: boolean
  /** `trigger` is the activated button, so the shell can restore focus to it. */
  onActivate: (id: string, trigger: HTMLElement | null) => void
  onContextMenu: (x: number, y: number, target: EventTarget | null) => void
  onReorder: (draggedId: string, targetId: string) => void
}): ReactNode {
  const { items, activeId, dockMode, onActivate, onContextMenu, onReorder } = props
  const [draggingId, setDraggingId] = useState<string | null>(null)
  const [overId, setOverId] = useState<string | null>(null)
  const [hoverIndex, setHoverIndex] = useState<number | null>(null)
  return createElement('div', {
    className: 'dsh-wb-activity',
    // Right-click anywhere on the activity bar (icons or blank space)
    // opens the dock position menu.
    onContextMenu: (event: MouseEvent) => {
      event.preventDefault()
      onContextMenu(event.clientX, event.clientY, event.target)
    },
  },
  items.map((item, index) => createElement('button', {
    key: item.id,
    className: [
      activeId === item.id ? 'active' : undefined,
      draggingId === item.id ? 'dragging' : undefined,
      overId === item.id ? 'drag-over' : undefined,
      // Fisheye magnification in dock mode: hovered item grows, neighbours nudge.
      dockMode && hoverIndex === index ? 'dock-hover' : undefined,
      dockMode && hoverIndex !== null && Math.abs(hoverIndex - index) === 1 ? 'dock-near' : undefined,
    ].filter(Boolean).join(' ') || undefined,
    title: item.title,
    draggable: true,
    onClick: (event: MouseEvent) => onActivate(item.id, event.currentTarget instanceof HTMLElement ? event.currentTarget : null),
    onMouseEnter: () => { if (dockMode) setHoverIndex(index) },
    onMouseLeave: () => { if (dockMode) setHoverIndex(null) },
    onDragStart: (event: DragEvent) => {
      setDraggingId(item.id)
      event.dataTransfer?.setData('text/plain', item.id)
      event.dataTransfer!.effectAllowed = 'move'
    },
    onDragEnd: () => { setDraggingId(null); setOverId(null) },
    onDragOver: (event: DragEvent) => {
      event.preventDefault()
      if (draggingId !== null && draggingId !== item.id) setOverId(item.id)
    },
    onDragLeave: () => { if (overId === item.id) setOverId(null) },
    onDrop: (event: DragEvent) => {
      event.preventDefault()
      const dragged = draggingId ?? event.dataTransfer?.getData('text/plain')
      if (dragged !== undefined && dragged !== item.id) onReorder(dragged, item.id)
      setDraggingId(null)
      setOverId(null)
    },
  }, renderIcon(item.icon, 18))),
  )
}

function EditorArea(props: {
  ctx: WorkbenchContext
  service: WorkbenchService
  store: LayoutStore
  tabs: EditorTab[]
  activeTab: string | null
  views: ViewDefinition[]
  sessionId: string | undefined
}): ReactNode {
  const { ctx, service, store, tabs, activeTab, views, sessionId } = props
  const viewById = useMemo(() => new Map(views.map((view) => [view.id, view])), [views])
  const activeTabEntry = activeTab === null ? undefined : tabs.find((tab) => tab.instanceId === activeTab)
  const activeView = activeTabEntry === undefined ? undefined : viewById.get(activeTabEntry.viewId)
  return createElement('div', { className: 'dsh-wb-editor' },
    tabs.length > 0
      ? createElement('div', { className: 'dsh-wb-tabs' },
        tabs.map((tab) => {
          const view = viewById.get(tab.viewId)
          if (view === undefined) return null
          const seedTitle = (tab.seed as { title?: string } | undefined)?.title
          return createElement('div', {
            key: tab.instanceId,
            className: `dsh-wb-tab${activeTab === tab.instanceId ? ' active' : ''}`,
            onClick: () => store.update({ activeEditorTab: tab.instanceId }),
          },
          view.icon !== undefined ? renderIcon(view.icon, 14) : null,
          seedTitle ?? titleOf(view),
          createElement('button', {
            className: 'dsh-wb-tab-close',
            title: 'Close',
            onClick: (event: MouseEvent) => {
              event.stopPropagation()
              service.closeViewInstance(tab.instanceId)
            },
          }, '×'),
          )
        }),
      )
      : null,
    activeView !== undefined && activeTabEntry !== undefined
      ? renderView(ctx, activeView, activeView.id, sessionId, true, activeTabEntry.seed)
      : null,
  )
}

function StatusBar(props: { items: ReturnType<WorkbenchService['getStatusItems']>; ctx: WorkbenchContext }): ReactNode {
  const { items, ctx } = props
  return createElement('div', { className: 'dsh-wb-statusbar' },
    items.map((item) => createElement('span', { key: item.id }, createElement(item.component, { ctx }))),
  )
}

/**
 * Live active-session id: subscribes to the uiSession scope adapter's current
 * binding, so switching the workspace/conversation re-renders and every view
 * keyed on sessionId reloads against the new working directory. Returns
 * undefined when the uiSession service is absent or no Session is selected.
 *
 * The sessions service no longer owns selection: its list snapshot carried a
 * `current` field through 0.1.x and the 0.2 client dropped it ("navigation
 * belongs to view owners"). The view owner's binding is `uiSession.adapter.current`,
 * whose snapshot exposes the scope identity as `key`.
 */
function useSessionId(ctx: WorkbenchContext): string | undefined {
  const uiSession = ctx.get<{
    adapter?: {
      current?: { subscribe(cb: () => void): () => void; getSnapshot(): { key?: string } }
    }
  }>('uiSession')
  const current = uiSession?.adapter?.current
  return useSyncExternalStore(
    (cb) => current?.subscribe(cb) ?? (() => {}),
    () => current?.getSnapshot().key,
  )
}
